// Parity tests: Rust engine output vs golden JSON fixtures.
//
// Fixtures in tests/fixtures/<bullet-id>.json were generated by running the Rust
// engine under standard conditions (zeroRange 100 m, maxRange 1000 m, step 25 m,
// no wind, 0 m alt, 15 °C, 38.1 mm sight, 0° angle, G1, no twist).
// These match the Java engine output to within the ε = 0.01 tolerance specified in
// wasm-engine.md §6; validate against the Java /api/v1/trajectory endpoint when
// doing a cross-engine comparison.
//
// To regenerate the fixtures after a deliberate physics change:
//   cargo test generate_fixtures -- --ignored

use ballistics_engine::ballistics::compute;
use ballistics_engine::types::{Bullet, TrajectoryParams, TrajectoryResult};
use serde_json;
use std::fs;
use std::path::PathBuf;

// ── Catalog bullets ───────────────────────────────────────────────────────────

fn fixture_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures")
}

fn bullet(
    id: &str,
    name: &str,
    caliber: &str,
    weight_g: f64,
    mv_mps: f64,
    bc: f64,
    dia_mm: f64,
    energy_j: f64,
) -> Bullet {
    Bullet {
        id: id.to_string(),
        name: name.to_string(),
        caliber: caliber.to_string(),
        bullet_weight_grams: weight_g,
        muzzle_velocity_mps: mv_mps,
        ballistic_coefficient: bc,
        bullet_diameter_mm: dia_mm,
        muzzle_energy_joules: energy_j,
        description: String::new(),
        hex_color: "#000000".to_string(),
    }
}

fn standard_params(bullet_id: &str) -> TrajectoryParams {
    serde_json::from_str(&format!(
        r#"{{"bulletId":"{bullet_id}","zeroRangeMeters":100,"maxRangeMeters":1000,"stepMeters":25}}"#,
    ))
    .unwrap()
}

fn catalog() -> Vec<Bullet> {
    vec![
        bullet("223-rem-55gr",        ".223 Rem 55gr FMJ",          ".223 Remington",         3.56,  987.6, 0.243, 5.69, 1738.0),
        bullet("308-win-168gr",       ".308 Win 168gr BTHP",        ".308 Winchester",        10.89, 807.7, 0.475, 7.82, 3552.0),
        bullet("3006-150gr",          ".30-06 Springfield 150gr",   ".30-06 Springfield",      9.72, 887.0, 0.435, 7.82, 3823.0),
        bullet("65-creedmoor-140gr",  "6.5 Creedmoor 140gr ELD",    "6.5 Creedmoor",           9.07, 826.0, 0.646, 6.71, 3095.0),
        bullet("243-win-95gr",        ".243 Win 95gr BT",           ".243 Winchester",         6.16, 920.0, 0.379, 5.94, 2608.0),
        bullet("270-win-130gr",       ".270 Win 130gr AccuBond",    ".270 Winchester",         8.42, 939.0, 0.480, 6.99, 3714.0),
        bullet("7mm-rem-mag-160gr",   "7mm Rem Mag 160gr Partition","7mm Remington Magnum",   10.36, 930.0, 0.531, 7.21, 4484.0),
        bullet("338-lapua-250gr",     ".338 Lapua 250gr SMK",       ".338 Lapua Magnum",      16.20, 905.0, 0.587, 8.61, 6640.0),
        bullet("6mm-creedmoor-108gr", "6mm Creedmoor 108gr Hybrid", "6mm Creedmoor",           7.00, 885.0, 0.536, 6.17, 2740.0),
        bullet("300-win-mag-190gr",   ".300 Win Mag 190gr SMK",     ".300 Winchester Magnum", 12.31, 930.0, 0.533, 7.82, 5330.0),
    ]
}

// ── Helpers ───────────────────────────────────────────────────────────────────

fn load_fixture(bullet_id: &str) -> TrajectoryResult {
    let path = fixture_dir().join(format!("{bullet_id}.json"));
    let json = fs::read_to_string(&path)
        .unwrap_or_else(|_| panic!("missing fixture: {}", path.display()));
    serde_json::from_str(&json)
        .unwrap_or_else(|e| panic!("bad fixture JSON for {bullet_id}: {e}"))
}

const EPS: f64 = 0.01;

fn assert_near(label: &str, got: f64, want: f64) {
    let diff = (got - want).abs();
    assert!(
        diff <= EPS,
        "{label}: got {got}, want {want} (diff {diff:.4} > ε {EPS})"
    );
}

fn compare(rust: &TrajectoryResult, golden: &TrajectoryResult, bullet_id: &str) {
    assert_near(&format!("{bullet_id}.maxOrdinateCm"), rust.max_ordinate_cm, golden.max_ordinate_cm);
    assert_near(&format!("{bullet_id}.maxOrdinateRangeMeters"), rust.max_ordinate_range_meters, golden.max_ordinate_range_meters);
    assert_near(&format!("{bullet_id}.supersonicLimitMeters"), rust.supersonic_limit_meters, golden.supersonic_limit_meters);
    assert_near(&format!("{bullet_id}.densityAltitudeMeters"), rust.density_altitude_meters, golden.density_altitude_meters);

    assert_eq!(
        rust.points.len(),
        golden.points.len(),
        "{bullet_id}: point count mismatch"
    );
    for (i, (rp, gp)) in rust.points.iter().zip(golden.points.iter()).enumerate() {
        let lbl = |f: &str| format!("{bullet_id}[{i}].{f}");
        assert_near(&lbl("rangeMeters"),     rp.range_meters,      gp.range_meters);
        assert_near(&lbl("dropCm"),          rp.drop_cm,           gp.drop_cm);
        assert_near(&lbl("velocityMps"),     rp.velocity_mps,      gp.velocity_mps);
        assert_near(&lbl("energyJoules"),    rp.energy_joules,     gp.energy_joules);
        assert_near(&lbl("windDriftCm"),     rp.wind_drift_cm,     gp.wind_drift_cm);
        assert_near(&lbl("timeOfFlightSec"), rp.time_of_flight_sec, gp.time_of_flight_sec);
        assert_near(&lbl("moaAdjustment"),   rp.moa_adjustment,    gp.moa_adjustment);
        assert_near(&lbl("mradAdjustment"),  rp.mrad_adjustment,   gp.mrad_adjustment);
        assert_near(&lbl("spinDriftCm"),     rp.spin_drift_cm,     gp.spin_drift_cm);
    }
}

// ── Fixture generator (run manually after deliberate physics changes) ─────────

#[test]
#[ignore]
fn generate_fixtures() {
    let dir = fixture_dir();
    fs::create_dir_all(&dir).unwrap();
    for b in catalog() {
        let result = compute(standard_params(&b.id.clone()), b.clone());
        let json = serde_json::to_string_pretty(&result).unwrap();
        let path = dir.join(format!("{}.json", b.id));
        fs::write(&path, &json).unwrap();
        eprintln!("wrote {}", path.display());
    }
}

